package com.ashkan.hotel;

import java.sql.*;
import java.time.LocalDate;
import java.util.*;

/** Read/write persistence adapter for financial BI. All dates are inclusive and currency-aware. */
public final class FinancialReportingRepository extends JdbcDomainRepository {
    public FinancialReportingRepository(String url,String user,String password,int poolSize){super(url,user,password,poolSize);}
    public List<FinancialAnalyticsService.Payment> payments(LocalDate from,LocalDate through)throws SQLException{return withConnection(c->{String sql="SELECT transaction_id,provider_reference,created_at::date,amount,currency,status,method FROM payment_transactions WHERE created_at::date BETWEEN ? AND ? ORDER BY created_at";try(PreparedStatement p=c.prepareStatement(sql)){p.setObject(1,from);p.setObject(2,through);try(ResultSet r=p.executeQuery()){List<FinancialAnalyticsService.Payment> out=new ArrayList<>();while(r.next())out.add(new FinancialAnalyticsService.Payment(r.getString(1),r.getString(2),r.getDate(3).toLocalDate(),r.getBigDecimal(4),r.getString(5),r.getString(6),r.getString(7)));return List.copyOf(out);}}});}
    public List<FinancialAnalyticsService.Refund> refunds(LocalDate from,LocalDate through)throws SQLException{return withConnection(c->{String sql="SELECT refund_id,payment_id,created_at::date,amount,currency,status FROM payment_refunds WHERE created_at::date BETWEEN ? AND ? ORDER BY created_at";try(PreparedStatement p=c.prepareStatement(sql)){p.setObject(1,from);p.setObject(2,through);try(ResultSet r=p.executeQuery()){List<FinancialAnalyticsService.Refund> out=new ArrayList<>();while(r.next())out.add(new FinancialAnalyticsService.Refund(r.getString(1),r.getString(2),r.getDate(3).toLocalDate(),r.getBigDecimal(4),r.getString(5),r.getString(6)));return List.copyOf(out);}}});}
    public List<FinancialAnalyticsService.Expense> expenses(LocalDate from,LocalDate through)throws SQLException{return withConnection(c->{String sql="SELECT expense_id,expense_date,amount,currency,category FROM financial_expenses WHERE expense_date BETWEEN ? AND ? ORDER BY expense_date";try(PreparedStatement p=c.prepareStatement(sql)){p.setObject(1,from);p.setObject(2,through);try(ResultSet r=p.executeQuery()){List<FinancialAnalyticsService.Expense> out=new ArrayList<>();while(r.next())out.add(new FinancialAnalyticsService.Expense(r.getString(1),r.getDate(2).toLocalDate(),r.getBigDecimal(3),r.getString(4),r.getString(5)));return List.copyOf(out);}}});}
    public void addExpense(FinancialAnalyticsService.Expense e)throws SQLException{withConnection(c->{try(PreparedStatement p=c.prepareStatement("INSERT INTO financial_expenses(expense_id,expense_date,amount,currency,category) VALUES(?,?,?,?,?) ON CONFLICT(expense_id) DO NOTHING")){p.setString(1,e.id());p.setObject(2,e.date());p.setBigDecimal(3,e.amount());p.setString(4,e.currency());p.setString(5,e.category());if(p.executeUpdate()!=1)throw new SQLException("Expense ID already exists");}return null;});}
    public List<FinancialAnalyticsService.Payment> capturedPayments(LocalDate from,LocalDate through)throws SQLException{return payments(from,through).stream().filter(p->"CAPTURED".equals(p.status())).toList();}
}
